        "accent": "neutral"
      }
    },
    {
      "component": "bullet-list",
      "props": {
        "heading": "Key Risk Areas",
        "items": [
          "Vendor concentration: heavy reliance on a small set of critical suppliers",
          "On-call fatigue: sustained incident load straining engineering response capacity",
